xql_query:
// ============================================================
// Rule: Dataset cisco_switch health check de ingestão
// Vendor: Cisco
// Objective:
// Detect activity associated with Dataset cisco_switch health check de ingestão.
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================

dataset = cisco_switch_raw
| comp max(_time) as last_seen
| alter minutes_since_last = timestamp_diff(current_time(), last_seen, "MINUTE")
| filter minutes_since_last > 10
| fields last_seen, minutes_since_last
